<script lang="ts">
  const VALID_STATES = ['novo', 'bom', 'marcas_de_uso', 'danificado', 'manutencao', 'baixado'];
  let { onClose, onSaved }: { onClose: () => void; onSaved: (item: Record<string, unknown>) => void } = $props();
  let form = $state({ patrimonio: '', marca: '', modelo: '', numeroSerie: '', estado: 'bom', observacoes: '' }); let erro = $state(''); let salvando = $state(false);
  async function salvar() { if (!form.patrimonio.trim() || !form.marca.trim() || !form.modelo.trim()) { erro = 'Preencha os campos obrigatórios.'; return; } salvando = true; try { const response = await fetch('/api/equipamentos/monitor', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (response.status === 401) { window.location.assign('/login'); return; } if (!response.ok) { erro = response.status === 409 ? 'Patrimônio já cadastrado.' : 'Não foi possível cadastrar o monitor.'; return; } onSaved(await response.json()); } catch { erro = 'Não foi possível cadastrar o monitor. Tente novamente.'; } finally { salvando = false; } }
</script>
<div class="modal edit-person-modal" role="presentation" onclick={(event) => event.target === event.currentTarget && !salvando && onClose()}><div class="modal__content edit-person-dialog card panel" role="dialog" aria-modal="true" aria-labelledby="monitor-title"><div class="edit-person-heading"><h2 id="monitor-title">Adicionar monitor</h2><button class="button--secondary edit-person-close" type="button" onclick={onClose}>×</button></div><form onsubmit={(event) => { event.preventDefault(); salvar(); }}><div class="form-grid">{#each [['patrimonio','Patrimônio'],['marca','Marca'],['modelo','Modelo'],['numeroSerie','Número de série']] as field}<div class="form-group"><label for={`monitor-${field[0]}`}>{field[1]}</label><input id={`monitor-${field[0]}`} bind:value={form[field[0] as keyof typeof form]} disabled={salvando} /></div>{/each}<div class="form-group"><label for="monitor-estado">Estado</label><select id="monitor-estado" bind:value={form.estado}>{#each VALID_STATES as state}<option value={state}>{state}</option>{/each}</select></div><div class="form-group"><label for="monitor-observacoes">Observações</label><textarea id="monitor-observacoes" bind:value={form.observacoes}></textarea></div></div>{#if erro}<p class="form-error" role="alert">{erro}</p>{/if}<footer class="form-actions edit-person-actions"><button class="button--secondary" type="button" onclick={onClose}>Cancelar</button><button class="button--primary" type="submit" disabled={salvando}>Salvar</button></footer></form></div></div>
